        "cdd048abc5f241ecba15f457ddabbeed": {
          "id": "cdd048abc5f241ecba15f457ddabbeed",
          "name": "Chama DeepSeek 1",
          "script": "(function execute() {\n    var dsUtils = new DeepSeekSaberUtils();\n    \n    var pergunta = vaInputs.prompt_1.toString();\n    // Substitui quebras de linha reais por espaços ou \\n escapado\n    var historicoAtual = (vaVars.historico || \"\").replace(/[\\n\\r]/g, \" \"); \n\n    var resposta = dsUtils.perguntarComHistorico(pergunta, historicoAtual);\n\n    // Limpa a resposta da IA de caracteres de controle antes de salvar no histórico\n    var respostaLimpa = resposta.replace(/[\\n\\r]/g, \" \");\n    \n    var novaInteracao = \" P: \" + pergunta + \" A: \" + respostaLimpa;\n    vaVars.historico = (historicoAtual + novaInteracao).substring(0, 2000); // Garante o limite de 2k caracteres\n\n    vaVars.resposta_ia = resposta;\n})()",
          "stepType": "ScriptAction",
          "applicability": {
            "value": "",
            "mode": "query"
          }
        },
